INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000259',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss finance at B2","Use Finanzwirtschaft vocabulary","Talk about financial markets and instruments"],"explanation":{"intro":"Finance vocabulary covers financial markets, instruments, and institutions at B2.","culturalNote":"Finanzwirtschaft in Germany: Deutschland hat eine bankbasierte Finanzierung (bank-based finance — vs. capital-market-based Anglo-Saxon model). Hausbank (house bank — long-term relationship between bank and firm). Key players: Deutsche Bank, Commerzbank, Sparkassen (savings banks — public, regional), Genossenschaftsbanken (cooperative banks). Frankfurt als Finanzplatz (financial centre — EZB/ECB, Deutsche Börse). Key instruments: Aktie (share), Anleihe (bond), Derivat (derivative), Fonds (fund). Bundesanleihe (German government bond — Bund)."},"examples":[{"german":"Das deutsche Finanzsystem beruht traditionell stärker auf langfristigen Bankbeziehungen als auf Kapitalmärkten, was deutschen Unternehmen eine stabilere, aber weniger flexible Finanzierungsstruktur verleiht.","english":"The German financial system has traditionally rested more on long-term bank relationships than on capital markets, which gives German companies a more stable but less flexible financing structure."},{"german":"Finanzderivate ermöglichen einerseits die Absicherung gegen Preisrisiken, werden andererseits aber auch zur Spekulation genutzt und können systemische Risiken verstärken.","english":"Financial derivatives enable, on the one hand, hedging against price risks, but on the other hand are also used for speculation and can amplify systemic risks."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss German finance, banking, financial instruments, and Frankfurt''s role at B2."}}',
'{"items":[{"word":"verleihen","translation":"to give/confer (a quality)","pronunciation":"fer-LY-en","example":"Stabilität verleihen."},{"word":"die Absicherung","translation":"hedging/protection","pronunciation":"dee AP-zi-khe-roong","example":"Absicherung gegen Risiken."},{"word":"systemisch","translation":"systemic","pronunciation":"zys-TAY-mish","example":"Systemische Risiken."},{"word":"verstärken","translation":"to amplify/reinforce","pronunciation":"fer-SHTER-ken","example":"Risiken verstärken."},{"word":"bankbasiert","translation":"bank-based","pronunciation":"BANK-bah-zeert","example":"Bankbasiertes System."},{"word":"die Finanzierungsstruktur","translation":"financing structure","pronunciation":"dee fi-nan-TSEER-oonks-shtrook-toor","example":"Finanzierungsstruktur."}]}',
'{"title":"Etwas verleiht jemandem/etwas X — confers X upon someone/something","pattern":"etwas verleiht + dative + accusative = something confers/gives (a quality, character, status) upon (more formal than geben — used when one thing grants a quality to another)","explanation":"Verleihen = to confer, to lend (a quality, character, or attribute). Das verleiht deutschen Unternehmen eine stabilere Struktur = This confers a more stable structure on German companies. Different from geben (to give — more concrete) or schenken (to give as gift). Verleihen implies conferring a quality or status: also used for: Auszeichnung verleihen (to confer an award), Glaubwürdigkeit verleihen (to lend credibility), Bedeutung verleihen (to give/lend significance to). Perfect: hat verliehen.","examples":[{"sentence":"Der Preis verleiht dem Projekt öffentliche Sichtbarkeit.","translation":"The prize confers public visibility on the project."},{"sentence":"Die Erfahrung verleiht ihrer Argumentation Überzeugungskraft.","translation":"The experience lends persuasive force to her argumentation."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Systemisch'' means?","options":["systemic","systematic","system-wide","structural"],"correctAnswer":"systemic"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The German financial system has traditionally rested more on long-term bank relationships than on capital markets, which gives German companies a more stable but less flexible financing structure.","options":["Das deutsche Finanzsystem beruht traditionell stärker auf langfristigen Bankbeziehungen als auf Kapitalmärkten, was deutschen Unternehmen eine stabilere, aber weniger flexible Finanzierungsstruktur verleiht.","Deutschland finanziert Unternehmen mehr über Banken als über die Börse.","Das Hausbankprinzip ist ein Merkmal des deutschen Finanzsystems.","Bankkredite sind in Deutschland wichtiger als Kapitalmarktfinanzierung."],"correctAnswer":"Das deutsche Finanzsystem beruht traditionell stärker auf langfristigen Bankbeziehungen als auf Kapitalmärkten, was deutschen Unternehmen eine stabilere, aber weniger flexible Finanzierungsstruktur verleiht."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Der Preis verleiht dem Projekt öffentliche ___.","options":["Sichtbarkeit","Bekanntheit","Aufmerksamkeit","Präsenz"],"correctAnswer":"Sichtbarkeit"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The experience lends persuasive force to her argumentation","wordBankItems":["Die","Erfahrung","verleiht","ihrer","Argumentation","Überzeugungskraft","."],"correctAnswer":"Die Erfahrung verleiht ihrer Argumentation Überzeugungskraft ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Absicherung'' means?","options":["hedging/protection","safeguarding","insurance","security"],"correctAnswer":"hedging/protection"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000025a',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss financial crises at B2","Use Finanzkrise vocabulary","Talk about 2008 crisis and systemic risk"],"explanation":{"intro":"Financial crisis vocabulary covers causes, mechanisms, and responses to financial crises at B2.","culturalNote":"Finanzkrise 2008: US Subprime-Krise (subprime crisis — cheap mortgages for low-income borrowers, securitised and sold globally as CDOs), Lehman Brothers collapse (September 2008 — systemic shock), Bankenkrise (banking crisis — European banks overexposed), Euroschuldenkrise (Euro debt crisis 2010-2012 — Greece, Ireland, Portugal, Spain, Italy — sovereign debt). Germany: Kurzarbeitergeld (short-time work — prevented mass unemployment), Konjunkturprogramm (stimulus program). ECB: Mario Draghi ''whatever it takes'' (2012). Key concept: systemisches Risiko (systemic risk — too-big-to-fail)."},"examples":[{"german":"Die Finanzkrise von 2008 offenbarte, wie vernetzte Finanzsysteme Schocks im Schneeballsystem multiplizieren und lokale Marktstörungen zu globalen Systemkrisen eskalieren lassen können.","english":"The financial crisis of 2008 revealed how networked financial systems can multiply shocks in a snowball system and allow local market disruptions to escalate into global systemic crises."},{"german":"Die staatliche Rettung systemrelevanter Banken löste eine fundamentale Verteilungsfrage aus: Verluste werden sozialisiert, während Gewinne privatisiert werden.","english":"The state rescue of systemically relevant banks triggered a fundamental question of distribution: losses are socialised, while profits are privatised."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss the 2008 financial crisis, systemic risk, and the socialisation of losses at B2."}}',
'{"items":[{"word":"offenbaren","translation":"to reveal","pronunciation":"o-fen-BAH-ren","example":"Eine Schwäche offenbaren."},{"word":"vernetzt","translation":"networked/interconnected","pronunciation":"fer-NETST","example":"Vernetztes System."},{"word":"multiplizieren","translation":"to multiply","pronunciation":"mul-ti-pli-TSEER-en","example":"Schocks multiplizieren."},{"word":"eskalieren","translation":"to escalate","pronunciation":"es-kah-LEER-en","example":"In eine Krise eskalieren."},{"word":"sozialisieren","translation":"to socialise","pronunciation":"zo-tsyah-li-ZEER-en","example":"Verluste sozialisieren."},{"word":"privatisieren","translation":"to privatise","pronunciation":"pri-vah-ti-ZEER-en","example":"Gewinne privatisieren."}]}',
'{"title":"Verluste sozialisieren, Gewinne privatisieren — socialising losses, privatising gains (political economy critique)","pattern":"Verluste werden sozialisiert, während Gewinne privatisiert werden = losses are socialised while gains are privatised (parallel passive construction highlighting asymmetry)","explanation":"Parallel passive construction: werden + Partizip II (present passive). Verluste werden sozialisiert = Losses are socialised (passive: while who socialises is left implicit — the state/taxpayer). Während Gewinne privatisiert werden = while profits are privatised (by the banks/private actors). The contrast (sozialisiert vs. privatisiert) using während (while) highlights an asymmetry — a rhetorical device. Passives here are impersonal (no stated agent) — emphasising the result/situation rather than the actor. Used as political critique of bailouts.","examples":[{"sentence":"Risiken werden vergemeinschaftet, während Erträge den Aktionären zufließen.","translation":"Risks are communalised, while returns flow to shareholders."},{"sentence":"Die Kosten werden auf die Allgemeinheit abgewälzt, während der Nutzen privatisiert bleibt.","translation":"The costs are shifted onto the general public, while the benefit remains private."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Offenbaren'' means?","options":["to reveal","to expose","to disclose","to show"],"correctAnswer":"to reveal"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The state rescue of systemically relevant banks triggered a fundamental question of distribution: losses are socialised, while profits are privatised.","options":["Die staatliche Rettung systemrelevanter Banken löste eine fundamentale Verteilungsfrage aus: Verluste werden sozialisiert, während Gewinne privatisiert werden.","Bankenrettung ist immer ein Transfer von öffentlichem Geld an private Akteure.","Wenn der Staat Banken rettet, zahlen Steuerzahler für private Fehler.","Bei Bankenrettungen werden Risiken vergesellschaftet, Gewinne aber nicht."],"correctAnswer":"Die staatliche Rettung systemrelevanter Banken löste eine fundamentale Verteilungsfrage aus: Verluste werden sozialisiert, während Gewinne privatisiert werden."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Risiken werden vergemeinschaftet, während Erträge den Aktionären ___.","options":["zufließen","zugutekommen","gehören","zufallen"],"correctAnswer":"zufließen"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The costs are shifted onto the general public while the benefit remains private","wordBankItems":["Die","Kosten","werden","auf","die","Allgemeinheit","abgewälzt",",","während","der","Nutzen","privatisiert","bleibt","."],"correctAnswer":"Die Kosten werden auf die Allgemeinheit abgewälzt , während der Nutzen privatisiert bleibt ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Eskalieren'' means?","options":["to escalate","to intensify","to worsen","to spread"],"correctAnswer":"to escalate"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000025b',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss currency and monetary policy at B2","Use Geldpolitik vocabulary","Talk about ECB, inflation, and interest rates"],"explanation":{"intro":"Currency and monetary policy vocabulary covers central banking, interest rate policy, and inflation at B2.","culturalNote":"Geldpolitik: EZB (Europäische Zentralbank — ECB, Frankfurt). German monetary tradition: Bundesbank (founded 1957 — independent, anti-inflationary — shaped ECB model). German Inflationstrauma (inflation trauma — 1923 Hyperinflation, 1948 currency reform — explains German aversion to inflation, austerity orientation). Key ECB instruments: Leitzins (key interest rate), Quantitative Easing (QE — Anleihekäufe), Forward Guidance. Post-2022: Inflationsbekämpfung (fighting inflation — highest inflation since 1973 in Germany). Preisstabilität (price stability — ECB mandate)."},"examples":[{"german":"Das Mandat der EZB, Preisstabilität zu gewährleisten, steht gelegentlich in Spannung mit anderen wirtschaftspolitischen Zielen wie Vollbeschäftigung oder der Finanzierung staatlicher Ausgaben.","english":"The ECB''s mandate to guarantee price stability is occasionally in tension with other economic policy goals such as full employment or the financing of state expenditure."},{"german":"Deutschlands tief verwurzeltes Inflationstrauma, das auf die Hyperinflation von 1923 zurückgeht, prägt bis heute die nationalstaatliche Präferenz für Geldwertstabilität und haushaltspolitische Disziplin.","english":"Germany''s deeply rooted inflation trauma, which goes back to the hyperinflation of 1923, continues to this day to shape the national preference for monetary stability and fiscal discipline."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss ECB monetary policy, German inflation trauma, and interest rate policy at B2."}}',
'{"items":[{"word":"das Mandat","translation":"mandate","pronunciation":"dahs man-DAHT","example":"Mandat der EZB."},{"word":"gelegentlich","translation":"occasionally","pronunciation":"geh-LAY-gent-likh","example":"Gelegentlich in Spannung."},{"word":"tief verwurzelt","translation":"deeply rooted","pronunciation":"teef fer-VOOORT-selt","example":"Tief verwurzeltes Trauma."},{"word":"zurückgehen auf","translation":"to go back to/date back to","pronunciation":"tsoo-RÜK-gay-en owf","example":"Auf 1923 zurückgehen."},{"word":"nationalstaatlich","translation":"national-state","pronunciation":"nah-tsyo-NAHL-shtaht-likh","example":"Nationalstaatliche Präferenz."},{"word":"haushaltspolitisch","translation":"fiscal","pronunciation":"HOWS-halts-po-li-tish","example":"Haushaltspolitische Disziplin."}]}',
'{"title":"Auf etwas zurückgehen — to go back to, to date back to (origin)","pattern":"etwas geht auf X zurück = something goes back to X, dates back to X (separable: geht...zurück; tracing the historical/causal origin of something)","explanation":"Auf etwas zurückgehen = to go back to, to date back to, to trace back to (separable: geht zurück, ging zurück, ist zurückgegangen — sein: change of state/movement). Das Trauma geht auf die Hyperinflation zurück = The trauma goes back to/dates back to the hyperinflation. Used to trace origins. Also: auf jemanden zurückgehen (to originate with a person), auf eine Quelle zurückgehen (to derive from a source). Compare: herrühren von (to stem from — more literary), entstammen (to derive from — more formal/genealogical), seinen Ursprung haben in (to have its origin in — more explicit).","examples":[{"sentence":"Der Begriff geht auf eine lateinische Wurzel zurück.","translation":"The term goes back to a Latin root."},{"sentence":"Der Konflikt geht auf ein Missverständnis aus dem Jahr 2020 zurück.","translation":"The conflict dates back to a misunderstanding from 2020."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Gelegentlich'' means?","options":["occasionally","sometimes","at times","periodically"],"correctAnswer":"occasionally"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Germany''s deeply rooted inflation trauma, which goes back to the hyperinflation of 1923, continues to this day to shape the national preference for monetary stability and fiscal discipline.","options":["Deutschlands tief verwurzeltes Inflationstrauma, das auf die Hyperinflation von 1923 zurückgeht, prägt bis heute die nationalstaatliche Präferenz für Geldwertstabilität und haushaltspolitische Disziplin.","Das deutsche Inflationstrauma von 1923 beeinflusst noch heute die Wirtschaftspolitik.","Deutschland hat eine historische Abneigung gegen Inflation wegen der Erfahrungen von 1923.","Die Hyperinflation hat langfristige Spuren in der deutschen Wirtschaftskultur hinterlassen."],"correctAnswer":"Deutschlands tief verwurzeltes Inflationstrauma, das auf die Hyperinflation von 1923 zurückgeht, prägt bis heute die nationalstaatliche Präferenz für Geldwertstabilität und haushaltspolitische Disziplin."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Der Begriff geht auf eine lateinische Wurzel ___.","options":["zurück","zurück","hervor","hinaus"],"correctAnswer":"zurück"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The conflict dates back to a misunderstanding from 2020","wordBankItems":["Der","Konflikt","geht","auf","ein","Missverständnis","aus","dem","Jahr","2020","zurück","."],"correctAnswer":"Der Konflikt geht auf ein Missverständnis aus dem Jahr 2020 zurück ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Tief verwurzelt'' means?","options":["deeply rooted","ingrained","entrenched","embedded"],"correctAnswer":"deeply rooted"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000025c',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss investments at B2","Use Investitionen vocabulary","Talk about capital allocation, risk, and return"],"explanation":{"intro":"Investment vocabulary covers capital allocation, risk-return trade-offs, and investment types at B2.","culturalNote":"Investitionen: Germany historically a low-equity-investment culture (Aktienkultur — stock culture — still weaker than UK/US: fewer Germans own shares, more savings in bank accounts). Key investment types: Aktien (equities), Anleihen (bonds), Immobilien (real estate — Betongold/concrete gold), Infrastruktur. Germany debate: Investitionslücke (investment gap — public investment low since 1990s), Germany invests less in infrastructure than other comparable countries. Öffentliche Investitionen (public investment — Schuldenbremse controversy). DAX (Deutscher Aktienindex — 40 companies)."},"examples":[{"german":"Investitionsentscheidungen sind grundsätzlich von einer Abwägung zwischen erwarteter Rendite und dem akzeptierten Risiko geprägt — ein Zusammenhang, der als Risiko-Rendite-Profil bezeichnet wird.","english":"Investment decisions are fundamentally shaped by a weighing of expected return against the accepted risk — a relationship that is referred to as the risk-return profile."},{"german":"Deutschlands chronische Investitionslücke bei öffentlicher Infrastruktur — Schulen, Straßen, Breitbandausbau — gefährdet langfristig die Wettbewerbsfähigkeit des Standorts.","english":"Germany''s chronic investment gap in public infrastructure — schools, roads, broadband expansion — threatens the competitiveness of the location in the long term."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss investment types, risk-return trade-offs, and Germany''s investment gap at B2."}}',
'{"items":[{"word":"die Abwägung","translation":"weighing/balancing","pronunciation":"dee AP-wä-goong","example":"Abwägung von Rendite und Risiko."},{"word":"die Rendite","translation":"return (on investment)","pronunciation":"dee ren-DEE-teh","example":"Erwartete Rendite."},{"word":"das Risiko-Rendite-Profil","translation":"risk-return profile","pronunciation":"dahs RIS-i-ko-ren-dee-teh-pro-feel","example":"Risiko-Rendite-Profil."},{"word":"die Investitionslücke","translation":"investment gap","pronunciation":"dee in-ves-ti-TSYOHNS-lük-eh","example":"Chronische Investitionslücke."},{"word":"chronisch","translation":"chronic","pronunciation":"KHROH-nish","example":"Chronische Unterinvestition."},{"word":"die Wettbewerbsfähigkeit","translation":"competitiveness","pronunciation":"dee VET-beh-verbs-fä-ikh-kyt","example":"Wettbewerbsfähigkeit des Standorts."}]}',
'{"title":"Als X bezeichnet werden — to be referred to as X, to be called X","pattern":"etwas wird als X bezeichnet = something is referred to as X, is called X (passive of bezeichnen; common way to introduce a technical term or label after explaining it)","explanation":"Als X bezeichnet werden = to be referred to as X, to be designated as X (passive of bezeichnen + als + nominative noun). Ein Zusammenhang, der als Risiko-Rendite-Profil bezeichnet wird = A relationship that is referred to as the risk-return profile. Active: man bezeichnet etwas als X = one refers to something as X. Compare: als X gelten (to be regarded as X — more evaluative), X heißen (to be called X — more informal/definitional), X nennen (to call X — active, less formal).","examples":[{"sentence":"Diese Methode wird als ''Best Practice'' bezeichnet.","translation":"This method is referred to as ''best practice''."},{"sentence":"Das Phänomen wird in der Fachsprache als Kavitation bezeichnet.","translation":"The phenomenon is referred to in technical language as cavitation."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Abwägung'' means?","options":["weighing/balancing","consideration","assessment","evaluation"],"correctAnswer":"weighing/balancing"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Investment decisions are fundamentally shaped by a weighing of expected return against the accepted risk — a relationship that is referred to as the risk-return profile.","options":["Investitionsentscheidungen sind grundsätzlich von einer Abwägung zwischen erwarteter Rendite und dem akzeptierten Risiko geprägt — ein Zusammenhang, der als Risiko-Rendite-Profil bezeichnet wird.","Investitionen müssen immer Risiko und Ertrag gegeneinander abwägen.","Das Verhältnis von Risiko und Rendite ist grundlegend für Anlageentscheidungen.","Jede Investition hat ein eigenes Risiko-Rendite-Verhältnis."],"correctAnswer":"Investitionsentscheidungen sind grundsätzlich von einer Abwägung zwischen erwarteter Rendite und dem akzeptierten Risiko geprägt — ein Zusammenhang, der als Risiko-Rendite-Profil bezeichnet wird."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Diese Methode wird als ''Best Practice'' ___.","options":["bezeichnet","genannt","beschrieben","eingestuft"],"correctAnswer":"bezeichnet"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The phenomenon is referred to in technical language as cavitation","wordBankItems":["Das","Phänomen","wird","in","der","Fachsprache","als","Kavitation","bezeichnet","."],"correctAnswer":"Das Phänomen wird in der Fachsprache als Kavitation bezeichnet ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Chronisch'' means?","options":["chronic","persistent","ongoing","recurrent"],"correctAnswer":"chronic"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000025d',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss corporate finance at B2","Use Unternehmensfinanzierung vocabulary","Talk about corporate funding, debt, and equity"],"explanation":{"intro":"Corporate finance vocabulary covers how firms fund themselves — equity, debt, and hybrid instruments at B2.","culturalNote":"Unternehmensfinanzierung: Eigenkapital (equity — Aktien, stille Einlage) vs. Fremdkapital (debt — Kredit, Anleihe). Germany: Mittelstand financing: Bankkredit (bank loan) dominant — less capital market. KfW (Kreditanstalt für Wiederaufbau — state development bank, funds SMEs, green investment). Deutsche Börse Venture Network. Key ratios: Eigenkapitalquote (equity ratio), Verschuldungsgrad (debt ratio). Venture Capital (VC) in Germany: Berlin tech scene (Rocket Internet, Zalando). Key decisions: Capital Structure — Modigliani-Miller theorem."},"examples":[{"german":"Die Kapitalstruktur eines Unternehmens bestimmt nicht nur seine Finanzierungskosten, sondern auch seinen Handlungsspielraum in wirtschaftlichen Krisenzeiten.","english":"A company''s capital structure determines not only its financing costs, but also its room for manoeuvre in times of economic crisis."},{"german":"Der deutsche Mittelstand finanziert sich überwiegend durch Innenfinanzierung und Bankkredite, was ihm größere Unabhängigkeit von Kapitalmarktvolatilität verleiht, aber den Zugang zu Wachstumskapital erschwert.","english":"German medium-sized companies finance themselves predominantly through internal financing and bank loans, which gives them greater independence from capital market volatility, but makes access to growth capital more difficult."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss corporate finance, Germany''s Mittelstand financing, and capital structure at B2."}}',
'{"items":[{"word":"der Handlungsspielraum","translation":"room for manoeuvre","pronunciation":"dayr HAND-looings-shpeel-rowm","example":"Handlungsspielraum haben."},{"word":"überwiegend","translation":"predominantly","pronunciation":"ü-ber-VEE-gend","example":"Überwiegend durch Innenfinanzierung."},{"word":"die Innenfinanzierung","translation":"internal financing","pronunciation":"dee IN-en-fi-nan-TSEER-oong","example":"Innenfinanzierung."},{"word":"die Volatilität","translation":"volatility","pronunciation":"dee vo-lah-ti-li-TÄT","example":"Kapitalmarktvolatilität."},{"word":"erschweren","translation":"to make more difficult","pronunciation":"er-SHVER-en","example":"Zugang erschweren."},{"word":"der Handlungsspielraum","translation":"room for manoeuvre","pronunciation":"dayr HAND-looings-shpeel-rowm","example":"Handlungsspielraum erweitern."}]}',
'{"title":"Nicht nur X bestimmen, sondern auch Y — determine not only X but also Y","pattern":"etwas bestimmt nicht nur X, sondern auch Y = something determines not only X but also Y (nicht nur...sondern auch highlights two parallel consequences)","explanation":"Bestimmt nicht nur X, sondern auch Y = determines not only X but also Y. Die Kapitalstruktur bestimmt nicht nur Finanzierungskosten, sondern auch Handlungsspielraum = The capital structure determines not only financing costs, but also room for manoeuvre. This pattern emphasises that something has broader effects than typically assumed (the second effect Y is often the more important/surprising one). Compare: beeinflusst ... und (influences ... and — less emphatic contrast), sowohl...als auch bestimmen (determine both...and — symmetric, no surprise element).","examples":[{"sentence":"Die Führungskultur bestimmt nicht nur die Mitarbeiterzufriedenheit, sondern auch die Innovationsfähigkeit.","translation":"Leadership culture determines not only employee satisfaction, but also the capacity for innovation."},{"sentence":"Das Bildungssystem bestimmt nicht nur individuelle Chancen, sondern auch die gesellschaftliche Kohäsion.","translation":"The education system determines not only individual opportunities, but also social cohesion."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Überwiegend'' means?","options":["predominantly","mainly","largely","chiefly"],"correctAnswer":"predominantly"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"A company''s capital structure determines not only its financing costs, but also its room for manoeuvre in times of economic crisis.","options":["Die Kapitalstruktur eines Unternehmens bestimmt nicht nur seine Finanzierungskosten, sondern auch seinen Handlungsspielraum in wirtschaftlichen Krisenzeiten.","Die Kapitalstruktur beeinflusst, wie teuer ein Unternehmen Geld aufnimmt.","Eigenkapital und Fremdkapital beeinflussen die finanzielle Flexibilität eines Unternehmens.","Wie ein Unternehmen finanziert ist, bestimmt seine Handlungsfähigkeit in der Krise."],"correctAnswer":"Die Kapitalstruktur eines Unternehmens bestimmt nicht nur seine Finanzierungskosten, sondern auch seinen Handlungsspielraum in wirtschaftlichen Krisenzeiten."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Führungskultur bestimmt nicht nur die Mitarbeiterzufriedenheit, sondern auch die ___.","options":["Innovationsfähigkeit","Produktivität","Effizienz","Motivation"],"correctAnswer":"Innovationsfähigkeit"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The education system determines not only individual opportunities but also social cohesion","wordBankItems":["Das","Bildungssystem","bestimmt","nicht","nur","individuelle","Chancen",",","sondern","auch","die","gesellschaftliche","Kohäsion","."],"correctAnswer":"Das Bildungssystem bestimmt nicht nur individuelle Chancen , sondern auch die gesellschaftliche Kohäsion ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Erschweren'' means?","options":["to make more difficult","to impede","to hinder","to complicate"],"correctAnswer":"to make more difficult"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000025e',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss tax policy at B2","Use Steuerpolitik vocabulary","Talk about tax systems, redistribution, and fiscal debate"],"explanation":{"intro":"Tax policy vocabulary covers taxation principles, Germany''s tax system, and redistribution at B2.","culturalNote":"Steuerpolitik in Deutschland: Key taxes: Einkommensteuer (income tax — progressive, up to 45%), Körperschaftsteuer (corporate tax — 15%), Mehrwertsteuer (VAT — 19%), Solidaritätszuschlag (solidarity surcharge — 5.5%, phased out for most since 2021), Gewerbesteuer (trade tax — municipal). Key debate: Steuerbelastung des Mittelstands (middle class tax burden), Steuerflucht (tax flight — multinationals), Digitalsteuer (digital tax). Key concept: Steuerprogression (tax progressivity — higher earners pay higher rate). Global: OECD Mindeststeuer (global minimum tax — 15%)."},"examples":[{"german":"Das Besteuerungsrecht des Staates ist in einem Rechtsstaat durch den Grundsatz der Gesetzmäßigkeit der Besteuerung gebunden: Steuern dürfen nur auf gesetzlicher Grundlage erhoben werden.","english":"The state''s right to tax is bound in a constitutional state by the principle of the legality of taxation: taxes may only be levied on a legal basis."},{"german":"Steuerpolitik ist inhärent umverteilend: Steuern entziehen dem Privaten Ressourcen und finanzieren öffentliche Güter, wobei progressive Steuern zusätzlich eine ausgleichende Wirkung auf die Einkommensverteilung haben.","english":"Tax policy is inherently redistributive: taxes extract resources from the private sphere and finance public goods, with progressive taxes additionally having an equalising effect on income distribution."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss tax policy, Germany''s tax system, and redistribution at B2."}}',
'{"items":[{"word":"die Gesetzmäßigkeit","translation":"legality/lawfulness","pronunciation":"dee geh-ZETS-mä-sikh-kyt","example":"Gesetzmäßigkeit der Besteuerung."},{"word":"erheben","translation":"to levy/impose (taxes)","pronunciation":"er-HAY-ben","example":"Steuern erheben."},{"word":"inhärent","translation":"inherently","pronunciation":"in-HÄ-rent","example":"Inhärent umverteilend."},{"word":"entziehen","translation":"to extract/withdraw","pronunciation":"ent-TSEE-en","example":"Ressourcen entziehen."},{"word":"ausgleichend","translation":"equalising","pronunciation":"OWS-gly-khend","example":"Ausgleichende Wirkung."},{"word":"progressiv","translation":"progressive","pronunciation":"pro-gres-SEEF","example":"Progressive Steuern."}]}',
'{"title":"Inhärent X sein — to be inherently X (something''s essential nature, not a contingent feature)","pattern":"etwas ist inhärent X = something is inherently X (inhärent = inherently — X is part of the essential nature, not a contingent or accidental feature)","explanation":"Inhärent = inherently (from Latin: inhaerentem — sticking to). Steuerpolitik ist inhärent umverteilend = Tax policy is inherently redistributive (this is its essential nature — cannot be changed without changing what tax policy is). Often used to challenge attempts to define something as accidentally/optionally having a property that is in fact intrinsic to it. Compare: von Natur aus (by nature — similar, often more biological), per se (per se — Latin equivalent), strukturell (structurally — more about system than essence), notwendigerweise (necessarily — more logical necessity).","examples":[{"sentence":"Macht ist inhärent korruptionsanfällig.","translation":"Power is inherently susceptible to corruption."},{"sentence":"Sprache ist inhärent mehrdeutig.","translation":"Language is inherently ambiguous."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Erheben'' means?","options":["to levy/impose (taxes)","to collect","to charge","to demand"],"correctAnswer":"to levy/impose (taxes)"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Tax policy is inherently redistributive: taxes extract resources from the private sphere and finance public goods, with progressive taxes additionally having an equalising effect on income distribution.","options":["Steuerpolitik ist inhärent umverteilend: Steuern entziehen dem Privaten Ressourcen und finanzieren öffentliche Güter, wobei progressive Steuern zusätzlich eine ausgleichende Wirkung auf die Einkommensverteilung haben.","Steuern finanzieren den Staat und haben eine Umverteilungsfunktion.","Progressive Steuern reduzieren Ungleichheit, indem sie höhere Einkommen stärker belasten.","Jedes Steuersystem verteilt Ressourcen zwischen Privaten und dem Staat um."],"correctAnswer":"Steuerpolitik ist inhärent umverteilend: Steuern entziehen dem Privaten Ressourcen und finanzieren öffentliche Güter, wobei progressive Steuern zusätzlich eine ausgleichende Wirkung auf die Einkommensverteilung haben."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Macht ist inhärent ___.","options":["korruptionsanfällig","korrumpierbar","missbrauchsanfällig","verführerisch"],"correctAnswer":"korruptionsanfällig"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Language is inherently ambiguous","wordBankItems":["Sprache","ist","inhärent","mehrdeutig","."],"correctAnswer":"Sprache ist inhärent mehrdeutig ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Ausgleichend'' means?","options":["equalising","balancing","compensating","levelling"],"correctAnswer":"equalising"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000025f',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss public debt at B2","Use Staatsverschuldung vocabulary","Talk about Germany''s Schuldenbremse and fiscal policy"],"explanation":{"intro":"Public debt vocabulary covers government borrowing, fiscal rules, and the German debt brake debate at B2.","culturalNote":"Staatsverschuldung in Deutschland: Schuldenbremse (debt brake — Article 109/115 Grundgesetz, 2009 — structural deficit maximum 0.35% GDP for federal government). Controversial: limits investment, pro-cyclical in crises. 2020: suspended for COVID stimulus. 2023: Bundesverfassungsgericht ruling (budget crisis — climate funds declared unconstitutional). Debate: Schwarze Null (black zero — balanced budget fetish) vs. Investitionspflicht (investment duty). EU: Stabilitätspakt (Stability and Growth Pact — 3% deficit, 60% debt ceiling). Keynesianismus vs. Ordoliberalismus."},"examples":[{"german":"Die Schuldenbremse schützt künftige Generationen vor übermäßiger Schuldenlast, kann aber bei dauerhafter Unterinvestition in öffentliche Infrastruktur und Bildung ähnlich belastend für die Zukunft wirken.","english":"The debt brake protects future generations from excessive debt burden, but with persistent underinvestment in public infrastructure and education can act similarly burdensome for the future."},{"german":"Die Frage, ob staatliche Schulden zur Finanzierung produktiver Investitionen gerechtfertigt sind, trennt Keynesianer von Ordoliberalen — ein Streit, der das politische Klima in Deutschland seit Jahrzehnten prägt.","english":"The question of whether government debt is justified for financing productive investments divides Keynesians from ordoliberals — a dispute that has shaped the political climate in Germany for decades."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss Germany''s Schuldenbremse, debt brake controversy, and fiscal policy at B2."}}',
'{"items":[{"word":"die Schuldenlast","translation":"debt burden","pronunciation":"dee SHOOL-den-last","example":"Übermäßige Schuldenlast."},{"word":"die Unterinvestition","translation":"underinvestment","pronunciation":"dee oon-ter-in-ves-ti-TSYOHN","example":"Dauerhafte Unterinvestition."},{"word":"ähnlich","translation":"similarly","pronunciation":"ÄN-likh","example":"Ähnlich belastend."},{"word":"trennen","translation":"to divide/separate","pronunciation":"TREN-en","example":"Keynesianer von Ordoliberalen trennen."},{"word":"der Streit","translation":"dispute/controversy","pronunciation":"dayr shtriyt","example":"Ein Streit, der prägt."},{"word":"produktiv","translation":"productive","pronunciation":"pro-dook-TEEF","example":"Produktive Investitionen."}]}',
'{"title":"Jemanden/etwas von jemandem/etwas trennen — to divide, to separate (intellectually or structurally)","pattern":"etwas/eine Frage trennt A von B = something/a question divides A from B (trennen here = to divide/separate into two camps — not physical separation)","explanation":"Etwas trennt A von B = something divides A from B (marks a dividing line between two groups, positions, or concepts). Die Frage trennt Keynesianer von Ordoliberalen = The question divides Keynesians from ordoliberals. This use of trennen focuses on intellectual or positional division (not necessarily opposition, just a clear distinction). Compare: unterscheiden von (to distinguish from — analytical distinction), unterschiedlicher Meinung sein (to be of different opinions — more personal), im Widerspruch stehen zu (to be in contradiction with — logical), scheiden between (literary — to separate).","examples":[{"sentence":"In dieser Frage trennt uns weniger als man denkt.","translation":"On this question, less divides us than one might think."},{"sentence":"Die Frage nach dem Grundeinkommen trennt Konservative von Progressiven.","translation":"The question of basic income divides conservatives from progressives."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Schuldenlast'' means?","options":["debt burden","debt load","financial burden","debt weight"],"correctAnswer":"debt burden"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The question of whether government debt is justified for financing productive investments divides Keynesians from ordoliberals — a dispute that has shaped the political climate in Germany for decades.","options":["Die Frage, ob staatliche Schulden zur Finanzierung produktiver Investitionen gerechtfertigt sind, trennt Keynesianer von Ordoliberalen — ein Streit, der das politische Klima in Deutschland seit Jahrzehnten prägt.","Öffentliche Investitionen durch Schulden zu finanzieren ist politisch umstritten.","Deutschland streitet über Schuldenbremse vs. Investitionsmöglichkeiten.","Keynesianer und Ordoliberale haben unterschiedliche Vorstellungen von Staatsverschuldung."],"correctAnswer":"Die Frage, ob staatliche Schulden zur Finanzierung produktiver Investitionen gerechtfertigt sind, trennt Keynesianer von Ordoliberalen — ein Streit, der das politische Klima in Deutschland seit Jahrzehnten prägt."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Frage nach dem Grundeinkommen trennt Konservative von ___.","options":["Progressiven","Liberalen","Sozialisten","Linken"],"correctAnswer":"Progressiven"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: On this question less divides us than one might think","wordBankItems":["In","dieser","Frage","trennt","uns","weniger","als","man","denkt","."],"correctAnswer":"In dieser Frage trennt uns weniger als man denkt ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Produktiv'' means?","options":["productive","profitable","fruitful","effective"],"correctAnswer":"productive"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000260',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss economic growth at B2","Use Wirtschaftswachstum vocabulary","Talk about growth theories and sustainability"],"explanation":{"intro":"Economic growth vocabulary covers growth theory, measurement, and the debate about growth and sustainability at B2.","culturalNote":"Wirtschaftswachstum: BIP (Bruttoinlandsprodukt — GDP, key measure). Germany: stagnation post-COVID (Wachstumsschwäche — growth weakness). Growth theories: Neoklassische Wachstumstheorie (Solow model — capital, labour, technology), Endogene Wachstumstheorie (endogenous growth — knowledge, innovation). Degrowth-Bewegung (post-growth movement — ecological critique of GDP growth). Post-growth economists: Raworth (Doughnut Economics), Jackson (Prosperity without Growth). Key debate: Is perpetual growth possible/desirable on a finite planet?"},"examples":[{"german":"Das Bruttoinlandsprodukt misst wirtschaftliche Aktivität, nicht aber gesellschaftliches Wohlergehen — es bewertet Krankheit und Rüstungsproduktion genauso wie Bildung und soziale Fürsorge.","english":"Gross domestic product measures economic activity, but not societal well-being — it values illness and armaments production just as it does education and social care."},{"german":"Die Degrowth-Bewegung argumentiert, dass das Ziel des wirtschaftlichen Wachstums mit den planetarischen Grenzen inkompatibel ist und durch Konzepte des Wohlbefindens in einer florierenden Gesellschaft ersetzt werden muss.","english":"The post-growth movement argues that the goal of economic growth is incompatible with planetary boundaries and must be replaced by concepts of well-being in a flourishing society."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss economic growth, GDP''s limitations, and the post-growth movement at B2."}}',
'{"items":[{"word":"das Wohlergehen","translation":"well-being","pronunciation":"dahs VOHL-er-gay-en","example":"Gesellschaftliches Wohlergehen."},{"word":"bewerten","translation":"to value/assess","pronunciation":"beh-VER-ten","example":"Genauso bewerten wie."},{"word":"die Rüstungsproduktion","translation":"armaments production","pronunciation":"dee RÜS-toonks-pro-dook-tsyohn","example":"Rüstungsproduktion."},{"word":"florierend","translation":"flourishing","pronunciation":"flo-REER-end","example":"Florierende Gesellschaft."},{"word":"inkompatibel","translation":"incompatible","pronunciation":"in-kom-pah-TEE-bel","example":"Inkompatibel mit Grenzen."},{"word":"planetarisch","translation":"planetary","pronunciation":"pla-neh-TAH-rish","example":"Planetarische Grenzen."}]}',
'{"title":"Nicht nur X, sondern genauso X wie Y — not only X but also Y just as much (equal valuation critique)","pattern":"etwas bewertet X genauso wie Y = something values/counts X just as much as Y (genauso wie = just as much as — neutral equivalence — used here critically: ill should NOT be worth as much as education)","explanation":"Genauso wie = just as much as, equally (marks equal treatment of two things that should not be equal — often in critical context). Das BIP bewertet Krankheit genauso wie Bildung = GDP values illness just as much as education (critique: the equivalence here is problematic). Genauso wie marks factual equivalence; the critical point is that this equivalence is wrong/unjust. Compare: gleichermaßen (equally — more neutral), auf die gleiche Stufe stellen wie (to place on the same level as — more explicit), unter denselben Gesichtspunkten betrachten (to view from the same perspective — more analytical).","examples":[{"sentence":"Das System behandelt alle Vergehen genauso wie schwere Verbrechen.","translation":"The system treats all offences just as it does serious crimes."},{"sentence":"Er bewertet kurzfristige Gewinne genauso wie langfristige Nachhaltigkeit.","translation":"He values short-term gains just as much as long-term sustainability."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Florierend'' means?","options":["flourishing","thriving","prosperous","booming"],"correctAnswer":"flourishing"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Gross domestic product measures economic activity, but not societal well-being — it values illness and armaments production just as it does education and social care.","options":["Das Bruttoinlandsprodukt misst wirtschaftliche Aktivität, nicht aber gesellschaftliches Wohlergehen — es bewertet Krankheit und Rüstungsproduktion genauso wie Bildung und soziale Fürsorge.","Das BIP ist kein geeignetes Maß für Wohlstand, weil es nicht unterscheidet.","GDP misst nur den Output, nicht den gesellschaftlichen Wert.","Das BIP hat methodische Grenzen, wenn es um Wohlbefinden geht."],"correctAnswer":"Das Bruttoinlandsprodukt misst wirtschaftliche Aktivität, nicht aber gesellschaftliches Wohlergehen — es bewertet Krankheit und Rüstungsproduktion genauso wie Bildung und soziale Fürsorge."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Er bewertet kurzfristige Gewinne genauso wie langfristige ___.","options":["Nachhaltigkeit","Sicherheit","Stabilität","Prosperität"],"correctAnswer":"Nachhaltigkeit"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The system treats all offences just as it does serious crimes","wordBankItems":["Das","System","behandelt","alle","Vergehen","genauso","wie","schwere","Verbrechen","."],"correctAnswer":"Das System behandelt alle Vergehen genauso wie schwere Verbrechen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Inkompatibel'' means?","options":["incompatible","inconsistent","irreconcilable","contradictory"],"correctAnswer":"incompatible"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000261',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss unemployment at B2","Use Arbeitslosigkeit vocabulary","Talk about unemployment types and labour market policy"],"explanation":{"intro":"Unemployment vocabulary covers types of unemployment, Germany''s labour market, and policy responses at B2.","culturalNote":"Arbeitslosigkeit: Types: Friktionsarbeitslosigkeit (frictional — between jobs), Strukturarbeitslosigkeit (structural — skills mismatch), Konjunkturelle Arbeitslosigkeit (cyclical — recession). Germany: Hartz IV reforms (2003-2005 Schröder Agenda 2010 — Arbeitslosengeld II/Bürgergeld, activation, lowered unemployment from ~12% to ~3%). Germany''s Arbeitsmarkt is currently tight (Fachkräftemangel — skilled worker shortage). Key institutions: Bundesagentur für Arbeit (Nürnberg), Jobcenter. Germany praised for: dual vocational training (Berufsausbildung), Kurzarbeit."},"examples":[{"german":"Strukturelle Arbeitslosigkeit ist resistenter gegenüber konjunkturellen Maßnahmen als zyklische Arbeitslosigkeit, da sie nicht auf mangelnde Nachfrage, sondern auf strukturelle Inkompatibilität zwischen Qualifikationsprofilen und Arbeitsnachfrage zurückgeht.","english":"Structural unemployment is more resistant to cyclical measures than cyclical unemployment, since it does not go back to insufficient demand, but to structural incompatibility between qualification profiles and labour demand."},{"german":"Deutschland hat durch das Kurzarbeiterprogramm verhindert, dass wirtschaftliche Schocks unmittelbar in Massenentlassungen und Qualifikationsverlust umschlagen.","english":"Germany has prevented, through the short-time work programme, economic shocks from immediately turning into mass redundancies and skills loss."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss unemployment types, Germany''s labour market reforms, and Kurzarbeit at B2."}}',
'{"items":[{"word":"resistent","translation":"resistant","pronunciation":"reh-zis-TENT","example":"Resistent gegenüber Maßnahmen."},{"word":"zyklisch","translation":"cyclical","pronunciation":"TSYK-lish","example":"Zyklische Arbeitslosigkeit."},{"word":"das Qualifikationsprofil","translation":"qualification profile","pronunciation":"dahs kvah-li-fi-kah-TSYOHNS-pro-feel","example":"Qualifikationsprofile."},{"word":"die Arbeitsnachfrage","translation":"labour demand","pronunciation":"dee AR-byts-nakh-frah-geh","example":"Arbeitsnachfrage."},{"word":"verhindern","translation":"to prevent","pronunciation":"fer-HIN-dern","example":"Massenentlassungen verhindern."},{"word":"unmittelbar","translation":"directly/immediately","pronunciation":"oon-MI-tel-bahr","example":"Unmittelbar umschlagen."}]}',
'{"title":"Verhindern, dass ... (etwas) geschieht — to prevent (something) from happening","pattern":"etwas/jemand verhindert, dass X geschieht = something/someone prevents X from happening (verhindern + dass-clause; the dass-clause describes what is prevented)","explanation":"Verhindern + dass-clause = to prevent from happening. Deutschland hat verhindert, dass Schocks in Massenentlassungen umschlagen = Germany prevented shocks from turning into mass redundancies. Alternatively: verhindern + infinitive construction (only when subject is the same person). Verhindern (to prevent) vs. verbieten (to prohibit — legal action), unterbinden (to stop — ongoing process), abwenden (to avert — usually negative events). Perfect: hat verhindert.","examples":[{"sentence":"Das Frühwarnsystem hat verhindert, dass die Krise eskalierte.","translation":"The early warning system prevented the crisis from escalating."},{"sentence":"Wir müssen verhindern, dass diese Fehler sich wiederholen.","translation":"We must prevent these mistakes from repeating themselves."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Resistent'' means?","options":["resistant","resilient","immune","robust"],"correctAnswer":"resistant"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Structural unemployment is more resistant to cyclical measures than cyclical unemployment, since it does not go back to insufficient demand, but to structural incompatibility between qualification profiles and labour demand.","options":["Strukturelle Arbeitslosigkeit ist resistenter gegenüber konjunkturellen Maßnahmen als zyklische Arbeitslosigkeit, da sie nicht auf mangelnde Nachfrage, sondern auf strukturelle Inkompatibilität zwischen Qualifikationsprofilen und Arbeitsnachfrage zurückgeht.","Strukturelle Arbeitslosigkeit ist schwerer zu bekämpfen als konjunkturelle.","Konjunkturprogramme helfen bei zyklischer, aber nicht bei struktureller Arbeitslosigkeit.","Strukturelle Arbeitslosigkeit entsteht, wenn Qualifikationen und Nachfrage nicht zusammenpassen."],"correctAnswer":"Strukturelle Arbeitslosigkeit ist resistenter gegenüber konjunkturellen Maßnahmen als zyklische Arbeitslosigkeit, da sie nicht auf mangelnde Nachfrage, sondern auf strukturelle Inkompatibilität zwischen Qualifikationsprofilen und Arbeitsnachfrage zurückgeht."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Das Frühwarnsystem hat verhindert, dass die Krise ___.","options":["eskalierte","ausbricht","entsteht","anschwoll"],"correctAnswer":"eskalierte"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: We must prevent these mistakes from repeating themselves","wordBankItems":["Wir","müssen","verhindern",",","dass","diese","Fehler","sich","wiederholen","."],"correctAnswer":"Wir müssen verhindern , dass diese Fehler sich wiederholen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Unmittelbar'' means?","options":["directly/immediately","instantly","at once","promptly"],"correctAnswer":"directly/immediately"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000262',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss the business cycle at B2","Use Konjunktur vocabulary","Talk about recession, recovery, and economic indicators"],"explanation":{"intro":"Business cycle vocabulary covers economic fluctuations, recession, and macroeconomic indicators at B2.","culturalNote":"Konjunktur: cyclical fluctuations in economic activity. Phases: Aufschwung (upswing/recovery), Boom (peak), Abschwung (downswing), Rezession (recession — 2 consecutive quarters of negative growth). Key indicators: BIP-Wachstum (GDP growth), ifo-Geschäftsklimaindex (ifo Business Climate Index — Munich — leading indicator), Arbeitslosenquote (unemployment rate), Inflation, PMI (Purchasing Managers Index). Germany: 2023-2024 Rezession, structural challenges (Energiepreise, Fachkräftemangel, Transformation). Key institutions: ifo Institut, DIW Berlin, SVR (Sachverständigenrat — council of economic experts)."},"examples":[{"german":"Konjunkturzyklen sind ein inhärentes Merkmal von Marktwirtschaften: Phasen der Expansion alternieren regelmäßig mit Kontraktion, deren Ausmaß und Dauer von multiplen Faktoren abhängen.","english":"Business cycles are an inherent feature of market economies: phases of expansion alternate regularly with contraction, the extent and duration of which depend on multiple factors."},{"german":"Die konjunkturelle Analyse erlaubt, zwischen temporären Schwankungen und strukturellen Veränderungen zu unterscheiden — eine Differenzierung, die für wirtschaftspolitische Entscheidungen von entscheidender Bedeutung ist.","english":"Business cycle analysis allows one to distinguish between temporary fluctuations and structural changes — a differentiation that is of decisive importance for economic policy decisions."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss the business cycle, recession, and German economic indicators at B2."}}',
'{"items":[{"word":"alternieren","translation":"to alternate","pronunciation":"al-ter-NEER-en","example":"Expansion und Kontraktion alternieren."},{"word":"das Ausmaß","translation":"extent/magnitude","pronunciation":"dahs OWS-mahs","example":"Ausmaß und Dauer."},{"word":"die Differenzierung","translation":"differentiation","pronunciation":"dee di-fe-ren-TSEER-oong","example":"Wichtige Differenzierung."},{"word":"temporär","translation":"temporary","pronunciation":"tem-po-RÄR","example":"Temporäre Schwankungen."},{"word":"von entscheidender Bedeutung","translation":"of decisive importance","pronunciation":"fon ent-SHYDE-en-der beh-DOY-toong","example":"Von entscheidender Bedeutung."},{"word":"die Schwankung","translation":"fluctuation","pronunciation":"dee SHVAN-koong","example":"Konjunkturelle Schwankungen."}]}',
'{"title":"Von entscheidender Bedeutung sein — to be of decisive importance","pattern":"etwas ist von entscheidender Bedeutung (für X) = something is of decisive importance (for X) — strong emphasis on the centrality of the factor","explanation":"Von entscheidender Bedeutung sein = to be of decisive importance. Stronger than wichtig (important) or bedeutend (significant). Entscheidend (decisive, determining) + Bedeutung (importance) = something that tips the scales. Other levels: von grundlegender Bedeutung (of fundamental importance — systemic), von großer Bedeutung (of great importance — less emphatic), von zentraler Bedeutung (of central importance). Von X Bedeutung sein (always von + adjective + Bedeutung — fixed structure).","examples":[{"sentence":"Der erste Eindruck ist von entscheidender Bedeutung.","translation":"The first impression is of decisive importance."},{"sentence":"Regelmäßige Kommunikation ist von entscheidender Bedeutung für den Projekterfolg.","translation":"Regular communication is of decisive importance for the project''s success."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Alternieren'' means?","options":["to alternate","to switch","to rotate","to oscillate"],"correctAnswer":"to alternate"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Business cycles are an inherent feature of market economies: phases of expansion alternate regularly with contraction, the extent and duration of which depend on multiple factors.","options":["Konjunkturzyklen sind ein inhärentes Merkmal von Marktwirtschaften: Phasen der Expansion alternieren regelmäßig mit Kontraktion, deren Ausmaß und Dauer von multiplen Faktoren abhängen.","Wirtschaftliche Auf- und Abschwünge sind ein normales Merkmal von Marktwirtschaften.","Konjunkturschwankungen sind unvermeidlich, aber ihre Intensität variiert.","In jeder Marktwirtschaft wechseln Phasen des Wachstums und der Rezession ab."],"correctAnswer":"Konjunkturzyklen sind ein inhärentes Merkmal von Marktwirtschaften: Phasen der Expansion alternieren regelmäßig mit Kontraktion, deren Ausmaß und Dauer von multiplen Faktoren abhängen."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Der erste Eindruck ist von entscheidender ___.","options":["Bedeutung","Wichtigkeit","Relevanz","Wirkung"],"correctAnswer":"Bedeutung"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Regular communication is of decisive importance for the project success","wordBankItems":["Regelmäßige","Kommunikation","ist","von","entscheidender","Bedeutung","für","den","Projekterfolg","."],"correctAnswer":"Regelmäßige Kommunikation ist von entscheidender Bedeutung für den Projekterfolg ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Temporär'' means?","options":["temporary","transient","provisional","short-term"],"correctAnswer":"temporary"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

